"""Dependency-free source syntax check; does not contact providers or run the app."""
import ast
from html.parser import HTMLParser
from pathlib import Path
import subprocess
import tempfile

root = Path(__file__).resolve().parents[1]
paths = subprocess.check_output(['git', 'ls-files', '-z'], cwd=root).decode().split('\0')
count = 0
class InlineScripts(HTMLParser):
    def __init__(self):
        super().__init__(); self.active=False; self.chunks=[]; self.scripts=[]
    def handle_starttag(self, tag, attrs):
        attrs=dict(attrs)
        if tag == 'script':
            self.active = not attrs.get('src') and attrs.get('type', '').lower() in ('', 'module', 'text/javascript', 'application/javascript')
            self.chunks=[]
    def handle_data(self, data):
        if self.active: self.chunks.append(data)
    def handle_endtag(self, tag):
        if tag == 'script' and self.active:
            self.scripts.append(''.join(self.chunks)); self.active=False
for name in paths:
    path = root / name
    if not path.is_file(): continue
    if path.suffix in ('.js', '.mjs', '.cjs'):
        subprocess.run(['node', '--check', str(path)], check=True); count += 1
    elif path.suffix == '.py':
        ast.parse(path.read_text(), filename=name); count += 1
    elif path.suffix == '.html':
        parser=InlineScripts(); parser.feed(path.read_text())
        for script in parser.scripts:
            with tempfile.TemporaryDirectory() as directory:
                probe=Path(directory)/'inline.mjs'; probe.write_text(script)
                subprocess.run(['node', '--check', str(probe)], check=True); count += 1
if not count: raise SystemExit('No supported source files checked.')
print(f'PASS: {count} JavaScript/Python source and inline-script syntax checks. TypeScript, browser behavior, and provider access were not exercised.')

