"""Check required environment names without printing credential values."""
import os
from pathlib import Path
import re
import sys

REQUIRED = ['MEDIA_BACKEND_KEY']
ENV_FILE = '.env.local'
values = {}
if ENV_FILE:
    path = Path(__file__).resolve().parents[1] / ENV_FILE
    if path.is_file():
        for raw in path.read_text().splitlines():
            match = re.match(r"^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*?)\s*$", raw)
            if match:
                value=match[2].split(' #', 1)[0].strip().strip('\"').strip("'")
                values[match[1]]=value
values.update(os.environ)
missing=[]
for name in REQUIRED:
    value=values.get(name, '').strip()
    if not value or value.lower().startswith(('replace-', 'your-', '<')):
        missing.append(name)
if 'CREDENTIAL_ENCRYPTION_KEY' in REQUIRED:
    if not re.fullmatch(r'[0-9a-fA-F]{64}', values.get('CREDENTIAL_ENCRYPTION_KEY', '')):
        if 'CREDENTIAL_ENCRYPTION_KEY' not in missing: missing.append('CREDENTIAL_ENCRYPTION_KEY (must be 64 hex characters)')
if missing:
    print('Missing or placeholder configuration: ' + ', '.join(missing))
    sys.exit(1)
print('PASS: Required configuration is present. Values were not printed; provider access was not tested.')
